const downloadSLRReport = () => {
  if (!slrData || !slrData.data) {
    return;
  }

  const rows = [];
  rows.push(['--- Purchase Orders Breakdown ---']);
  rows.push(['PO Number', 'Vendor Name', 'Type', 'Description', 'Total Amount', 'Actual', 'Commitment', 'Status']);

  const slrFiltered = slrData.data.filter((r: any) => (slrTypeFilter === 'ALL' || r.type === slrTypeFilter) && (slrStatusFilter === 'ALL' || r.status === slrStatusFilter));

  slrFiltered.forEach((row: any) => {
    const rawVendor = poVendorMap.get(row.po_document);
    const vendorName = row.type === 'PReq' ? '' : (rawVendor || 'Unknown Vendor');
    if (row.line_items?.length > 0) {
      row.line_items.forEach((item: any) => {
        rows.push([
          row.po_document || '',
          `"${vendorName.replace(/"/g, '""')}"`,
          item.type || '',
          `"${(item.description || '').replace(/"/g, '""')}"`,
          item.total || 0,
          item.actual || 0,
          item.commitment || 0,
          item.status || row.status || ''
        ]);
      });
    } else {
      rows.push([
        row.po_document || '',
        `"${vendorName.replace(/"/g, '""')}"`,
        row.type || '',
        `"${(row.description || '').replace(/"/g, '""')}"`,
        row.total || 0,
        row.actual || 0,
        row.commitment || 0,
        row.status || ''
      ]);
    }
  });

  const csvContent = "data:text/csv;charset=utf-8," + rows.map(e => e.join(",")).join("\n");
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `Purchase_Orders_Breakdown_${p.projectId}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};
